int nca(int x, int y, List<int> beta, List<int> alfa,
        List<int> tau, List<int> lam, List<int> pi) {
  // Find common height
  int h;
  if (beta[x] <= beta[y]) {
    h = lam[beta[y] & -beta[x]];
  } else {
    h = lam[beta[x] & -beta[y]];
  }

  // Find true height
  int k = alfa[x] & alfa[y] & -(1 << h);
  h = lam[k & -k];

  // Find beta[z]
  int j = ((beta[x] >> h) | 1) << h;

  // Find x' and y'
  if (j != beta[x]) {
    int l = lam[alfa[x] & ((1 << h) - 1)];
    x = tau[((beta[x] >> l) | 1) << l];
  }

  if (j != beta[y]) {
    int l = lam[alfa[y] & ((1 << h) - 1)];
    y = tau[((beta[y] >> l) | 1) << l];
  }

  // Find z
  int z = (pi[x] <= pi[y]) ? x : y;
  return z;
}

